import java.lang.reflect.*;
import java.util.*;

public final class PublicSurface {
    public static void main(String[] arguments) throws Exception {
        for (String name : arguments) {
            Class<?> owner = Class.forName(name, false, PublicSurface.class.getClassLoader());
            TreeSet<String> entries = new TreeSet<>();
            entries.add("TYPE " + Modifier.toString(owner.getModifiers()) + " " + owner.getName());
            for (Method method : owner.getMethods()) {
                entries.add("METHOD " + method.getName() + Arrays.toString(method.getParameterTypes())
                        + " -> " + method.getReturnType().getTypeName()
                        + " static=" + Modifier.isStatic(method.getModifiers()));
            }
            for (Constructor<?> constructor : owner.getDeclaredConstructors()) {
                if (Modifier.isPublic(constructor.getModifiers()) || Modifier.isProtected(constructor.getModifiers())) {
                    entries.add("CONSTRUCTOR " + Modifier.toString(constructor.getModifiers())
                            + Arrays.toString(constructor.getParameterTypes()));
                }
            }
            for (Field field : owner.getFields()) {
                entries.add("FIELD " + field.getName() + " " + field.getType().getTypeName()
                        + " " + Modifier.toString(field.getModifiers()));
            }
            for (String entry : entries) System.out.println(name + "\t" + entry);
        }
    }
}
